--- A/tools/nix/flake.nix
+++ B/tools/nix/flake.nix
@@ -3,7 +3,8 @@
 {
   description = "Nix-owned SCORE tooling selections";
   inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
-  outputs = { self, nixpkgs }:
+  inputs.ruffPkgs.url = "github:NixOS/nixpkgs/b6018f87da91d19d0ab4cf979885689b469cdd41";
+  outputs = { self, nixpkgs, ruffPkgs }:
     let
       systems = [ "x86_64-linux" "aarch64-linux" "aarch64-darwin" ];
       forAllSystems = nixpkgs.lib.genAttrs systems;
@@ -69,7 +70,8 @@
         let
           pkgs = import nixpkgs { inherit system; };
         in {
-          inherit (pkgs) actionlint bazelisk buildifier ruff shellcheck starpls uv yamlfmt;
+          inherit (pkgs) actionlint bazelisk buildifier shellcheck starpls uv yamlfmt;
+          ruff = (import ruffPkgs { inherit system; }).ruff;
           inherit (pkgs) pre-commit basedpyright codespell;
           apm = pkgs.apm-cli;
           opencode = opencodeFor system;
--- A/tools/nix/flake.lock
+++ B/tools/nix/flake.lock
@@ -18,7 +18,24 @@
     },
     "root": {
       "inputs": {
-        "nixpkgs": "nixpkgs"
+        "nixpkgs": "nixpkgs",
+        "ruffPkgs": "ruffPkgs"
+      }
+    },
+    "ruffPkgs": {
